// Views consume verified adapter data only. They never import the demo model.
export const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml;
const button=(label,action,disabled=false,outline=false)=>`<button type="button" class="button ${outline?'outline':''}" data-live-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
const facts=rows=>`<dl class="facts">${rows.map(([key,value])=>`<div><dt>${e(key)}</dt><dd>${e(value??'Not available')}</dd></div>`).join('')}</dl>`;
export function registrationPresentation(record){
  if(!record)return {step:0,title:'Create your kitchen',text:'Save your kitchen and first meal before authorizing deployment.'};
  const states={DRAFT:{step:1,title:'Draft saved',text:'Your first meal is private. Review the details, sign the authorization, then explicitly enable automatic deployment.'},PENDING:{step:2,title:'Deployment pending',text:'The original deployment is awaiting confirmation. Keep checking this registration.'},UNKNOWN:{step:2,title:'Deployment needs verification',text:'The result of the original deployment is uncertain. Check this registration; do not create a replacement.'},CONFIRMED:{step:2,title:'Contract confirmed · Check listing',text:'The contract is confirmed. The public listing has not been verified in this view; check the original progress.'}};
  if(record.state==='CONFIRMED'&&(record.listingConfirmed===true||record.businessReady===true))return {step:3,title:'Kitchen listed',text:record.businessReady===true?'Your kitchen and first meal are listed.':'Your kitchen and first meal are listed. Live business services are temporarily not ready.'};
  return states[record.state]??{step:2,title:'Check original registration',text:'The server returned an unrecognized status. No new deployment is enabled.'};
}
export function validateDraft(input,decimals=6){
  const errors={};
  for(const [key,label,max] of [['storeName','Kitchen name',120],['mealName','Meal name',120],['description','Description',2000]])if(!input[key]?.trim()||input[key].trim().length>max)errors[key]=`${label} is required (up to ${max} characters).`;
  if(!/^\d+(\.\d+)?$/.test(input.price??'')||!/[1-9]/.test(input.price)||((input.price.split('.')[1]??'').length>decimals))errors.price=`Enter a positive price with up to ${decimals} decimal places.`;
  if(!input.photo||!['image/jpeg','image/png','image/webp'].includes(input.photo.type)||input.photo.size<=0||input.photo.size>5*1024*1024)errors.photo='Choose a JPEG, PNG or WebP meal photo up to 5 MB.';
  if(!Array.isArray(input.windows)||!input.windows.length||input.windows.length>2||input.windows.some(([start,end])=>!Number.isInteger(start)||!Number.isInteger(end)||start<0||end>1440||start>=end||start%30!==0||end%30!==0)||input.windows.length===2&&input.windows[0][1]>input.windows[1][0])errors.windows='Choose 30-minute slots in start-time order, without overlaps and with an end after each start. Saved non-half-hour times must be reselected before saving.';
  return errors;
}
const time=value=>Number.isInteger(value)?`${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`:'';
export function halfHourOptions(selected,end=false,clockValues=false){
 const value=typeof selected==='number'?selected:/^\d{2}:\d{2}$/.test(selected??'')?Number(selected.slice(0,2))*60+Number(selected.slice(3)):null;
 const legacy=Number.isInteger(value)&&value>=0&&value<=(end?1440:1439)&&value%30!==0;
 const optionValue=n=>clockValues?time(n):String(n);
 return '<option value="">Choose</option>'+(legacy?`<option value="${optionValue(value)}" selected disabled>${time(value)} · Saved time; choose a 30-minute slot to save</option>`:'')+Array.from({length:end?49:48},(_,i)=>i*30).map(n=>`<option value="${optionValue(n)}" ${n===value?'selected':''}>${time(n)}</option>`).join('');
}
export const serviceHours=windows=>Array.isArray(windows)?windows.map(([a,b])=>`${time(a)}–${time(b)}`).join(' / '):'Not available';
export function priceLabel(units,decimals=6,symbol='test USDC'){
  if(!/^\d+$/.test(String(units??''))||!Number.isInteger(decimals)||decimals<0||decimals>36)return 'Price unavailable';
  const digits=String(units).padStart(decimals+1,'0'),fraction=decimals?digits.slice(-decimals).replace(/0+$/,''):'';
  return `${decimals?digits.slice(0,-decimals):digits}${fraction?'.'+fraction:''} ${symbol}`;
}
export function renderRegistration({context={},busy=false,blocked=false,error='',signed=false,draft={},errors={},preview=''}={}){
  const {session,setup={},registration:r,store}=context,p=registrationPresentation(r),canSave=!!session&&setup.registrationEnabled===true&&!r&&!busy&&!blocked&&!setup.registrationUnavailableReason;
  const field=(name,label,type='text')=>`<div class="form-field"><label for="register-${name}">${label}</label><input id="register-${name}" name="${name}" type="${type}" value="${e(draft[name]??'')}" ${name==='price'?'inputmode="decimal"':'maxlength="120"'} required aria-describedby="error-${name}" ${errors[name]?'aria-invalid="true"':''}><p class="field-error" id="error-${name}">${e(errors[name]??'')}</p></div>`;
  const windows=draft.windows??[['','']];
  const expired=r?.state==='DRAFT'&&/^\d+$/.test(r.request?.deadline??'')&&Number(r.request.deadline)<=Date.now()/1000;
  return `<div class="container page registration-page"><div class="breadcrumb"><a href="#home">MealForward home</a> / Open a kitchen</div><div class="page-heading"><div class="eyebrow">A PLACE AT THE TABLE</div><h1>Open your kitchen.</h1><p>One kitchen. Your first meal. A little kindness to share.</p></div>${setup.registrationUnavailableReason?'<p class="notice warning" role="status">This MVP already has its one test kitchen. Sign in with its owner wallet to continue; additional kitchen registration is unavailable in this run.</p>':''}<ol class="registration-steps" aria-label="Registration progress">${['Kitchen & first meal','Authorize deployment','Confirm & open'].map((label,i)=>`<li ${p.step===i||i===2&&p.step===3?'aria-current="step"':''} class="${p.step>i?'complete':''}"><span>${i+1}</span>${label}</li>`).join('')}</ol>${context.registrations?.length?`<section class="panel"><label for="original-registration">Your original registrations</label><select id="original-registration" ${busy?'disabled':''}><option value="">Choose a record to check</option>${context.registrations.map(item=>`<option value="${e(item.registrationId)}" ${r?.registrationId===item.registrationId?'selected':''}>${e(item.state)} · ${e(item.request?.name??item.storeId??'Kitchen')} · ${e(item.registrationId)}</option>`).join('')}</select><p class="muted">These records are not ordered by creation time. Choose the original record you want to continue.${context.hasMore?' More records exist; use your registration reference to recover one.':''}</p></section>`:''}<div class="registration-layout"><section><section class="panel"><h2>1. Wallet sign-in</h2><p>${session?`Signed in with <span class="wallet-address">${e(session.wallet)}</span>`:'Connect your wallet and sign the login message to find your kitchen or continue an existing registration.'}</p>${session?button('Sign out','logout',busy,true):button('Sign in with wallet','login',busy||setup.walletLoginEnabled!==true)}${!session&&setup.walletLoginEnabled!==true?'<p class="muted">Wallet sign-in is currently unavailable. Check the connection to continue.</p>':''}</section>${!r?`<form id="registration-form" class="panel"><h2>2. Kitchen & first meal</h2><p>Your draft stays private until deployment and publication are confirmed.</p><fieldset ${!canSave?'disabled':''}>${field('storeName','Kitchen name')}${field('mealName','First meal name')}<div class="form-field"><label for="register-description">Meal description</label><textarea id="register-description" name="description" maxlength="2000" required aria-describedby="error-description" ${errors.description?'aria-invalid="true"':''}>${e(draft.description??'')}</textarea><p class="field-error" id="error-description">${e(errors.description??'')}</p></div>${field('price',`Price per meal · ${e(setup.assetSymbol??'test USDC')}`)}<div class="form-field"><label for="register-photo">Meal photo</label><input type="file" id="register-photo" name="photo" accept="image/jpeg,image/png,image/webp" aria-describedby="error-photo photo-help"><p id="photo-help" class="form-help">JPEG, PNG or WebP · Up to 5 MB. Upload a photo of your meal.</p>${preview?`<img class="editor-image" src="${e(preview)}" alt="Unsaved first meal preview">`:''}${draft.photo?`<p class="muted">Photo selected · ${e(draft.photo.name)}</p>`:''}<p class="field-error" id="error-photo">${e(errors.photo??'')}</p></div><div class="form-field"><h3>Service time · Beijing time (UTC+8)</h3><p class="form-help">Choose hourly or half-hourly slots. End time may be 24:00. Saved non-half-hour times stay unchanged; reselect a 30-minute slot before saving.</p>${windows.map(([a,b],i)=>`<div class="service-time-row"><div><label for="register-start-${i}">Start ${i+1}</label><select id="register-start-${i}" name="start-${i}" required>${halfHourOptions(a,false,true)}</select></div><div><label for="register-end-${i}">End ${i+1}</label><select id="register-end-${i}" name="end-${i}" required>${halfHourOptions(b,true,true)}</select></div>${button('×','remove-time-'+i,windows.length===1,true)}</div>`).join('')}<p id="error-windows" class="field-error">${e(errors.windows??'')}</p>${button('Add service time','add-time',windows.length>=2,true)}</div><button class="button" type="submit">Save kitchen & first meal</button></fieldset>${!session?'<p class="muted">Sign in before saving your kitchen.</p>':setup.registrationEnabled!==true?'<p class="muted">Registration is currently unavailable.</p>':''}</form>`:`<section class="panel"><h2>${e(p.title)}</h2><p>${e(p.text)}</p>${facts([['Registration reference',r.registrationId],['Deployment state',r.state],['Original transaction hash',r.transactionHash||'Not yet returned'],['Kitchen contract',r.escrow||'Not yet returned'],['First meal publication',(r.listingConfirmed===true||r.businessReady===true)&&r.state==='CONFIRMED'?'Listed':'Not verified']])}${r.state==='DRAFT'?`<div class="notice">Review the saved kitchen and meal before signing. A signature authorizes deployment; it does not confirm deployment or publication.</div>${r.request?.firstMeal?facts([['Kitchen',r.request?.name],['First meal',r.request.firstMeal.name],['Description',r.request.firstMeal.description],['Price',priceLabel(r.request.firstMeal.unitPrice,setup.assetDecimals,setup.assetSymbol)],['Service time',serviceHours(r.request.firstMeal.windows)+' · Beijing time (UTC+8)']]):'<p class="muted">Saved details will appear when supplied by the server.</p>'}${expired?'<p class="notice warning">This draft authorization has expired. Keep this original reference and check with the service before continuing.</p>':''}<div class="order-actions">${button(signed?'Authorization signed':'Sign deployment authorization','sign',busy||blocked||!!setup.registrationUnavailableReason||expired||signed||r.walletActionsEnabled!==true)}${button('Enable automatic deployment','enable',busy||blocked||!!setup.registrationUnavailableReason||expired||!signed||r.walletActionsEnabled!==true)}</div>${signed&&!setup.registrationUnavailableReason?'<p class="muted">Signed for this registration. Click Enable automatic deployment to submit.</p>':''}`:''}<div class="order-actions">${button('Check original progress','refresh',busy,true)}${r.state==='CONFIRMED'&&(r.listingConfirmed===true||r.businessReady===true)&&hasOwnedKitchen(context)?'<a class="button" href="#merchant/overview">Enter my kitchen</a>':''}</div></section>`}</section><aside class="registration-aside"><h2>From your kitchen,<br>to the next person.</h2><p>Save your first meal, authorize the platform to deploy your kitchen, and follow its progress here.</p><p>Refreshing this page checks your original record. Pending or uncertain deployments keep the same registration reference.</p><p class="muted">Monad Testnet · Test assets have no real dollar value.</p>${button('Check connection & recover','recover',busy,true)}<form id="registration-recovery"><label for="registration-reference">Have a registration reference?</label><input id="registration-reference" name="registrationId" placeholder="0x…" pattern="0x[0-9a-fA-F]{64}" required ${busy?'disabled':''}><button class="text-button" ${!session||busy?'disabled':''}>Find original registration</button></form></aside></div><div id="live-feedback" role="status" aria-live="polite">${busy?'Please wait…':''}</div><p class="error" id="live-error" role="alert">${e(error)}</p></div>`;
}

function photo(meal){const path=meal?.imageUrl??(/^0x[0-9a-f]{64}$/i.test(meal?.imageDigest??'')?'/v1/registered-store-images/'+meal.imageDigest:/^[0-9a-f]{64}$/i.test(meal?.imageDigest??'')?'/v1/images/'+meal.imageDigest:null);return typeof path==='string'&&/^\/(?!\/)/.test(path)?`<img src="${e(path)}" alt="${e(meal.name)}" loading="lazy" width="400" height="240">`:'<div class="live-photo-placeholder">Meal photo</div>';}
export function renderLiveCards(stores=[],mealsByStore={},setup={}){
  return stores.map(store=>{const meal=(mealsByStore[store.id]??[]).find(m=>m.listed===true);return `<article class="store-card live-store-card"><a class="store-photo" href="#store/${encodeURIComponent(store.id)}">${photo(meal)}<div class="store-tag"><span>Registered kitchen</span></div></a><div class="store-body"><div class="store-heading"><h3><a href="#store/${encodeURIComponent(store.id)}">${e(store.name)}</a></h3></div><p class="store-description">${e(meal?.description??'No listed meals available.')}</p><p class="meal-name">${e(meal?.name??'Menu pending')}</p><p class="store-time">Service Time · ${e(serviceHours(meal?.windows))} · Beijing time (UTC+8)</p><p class="pill">${meal?`${e(meal.financial?.counts?.A??meal.available??'Not available')} available`:'No published meal'}</p><div class="store-bottom"><div class="price">${e(priceLabel(meal?.unitPrice,setup.assetDecimals,setup.assetSymbol))}</div><a class="button outline" href="#store/${encodeURIComponent(store.id)}">View kitchen</a></div></div></article>`;}).join('');
}
export function hasOwnedKitchen(context){return !!context?.session&&!!context?.store?.id&&Array.isArray(context.session.stores)&&context.session.stores.includes(context.store.id);}
const mealButton=(label,action,id='',disabled=false)=>`<button type="button" class="button outline" data-live-action="${action}" data-meal-id="${e(id)}" ${disabled?'disabled':''}>${label}</button>`;
export function renderLiveKitchen({context={},view='overview',meals=[],overview=null,error='',busy=false,capabilities={},unavailableReasons={},payouts=null,payoutsLoading=false}){
  const views=[['overview','Overview'],['meals','Meals'],['verify','Verify'],['payouts','Payouts']],store=context.store;if(!views.some(([v])=>v===view))view='overview';
  if(!hasOwnedKitchen(context))return `<div class="container page"><div class="page-heading"><h1>Kitchen workspace</h1><p>${context.session?'This wallet has no permission to manage this kitchen.':'Sign in with the kitchen owner wallet to manage meals.'}</p></div>${facts([['Current wallet',context.session?.wallet??'Not signed in']])}<div class="order-actions">${button(context.session?'Switch wallet / Sign in again':'Sign in with wallet',context.session?'switch-wallet':'login',busy)}<a class="button outline" href="#register">${context.registration?'Continue registration':'Kitchen registration'}</a>${store?`<a class="button outline" href="#store/${encodeURIComponent(store.id)}">Public kitchen · View only</a>`:'<a class="button outline" href="#stores">Browse public kitchens</a>'}</div></div>`;
  const menu=meals.map(meal=>{const draft=meal.draft??meal,shown=meal.published===false?draft:meal;return `<article class="meal-row"><div class="live-meal-photo">${photo(meal.published===false?draft:meal)}</div><div class="meal-row-copy"><h2>${e(shown.name??draft.name)}</h2><p>${e(shown.description??draft.description)}</p><p class="meal-price">${e(priceLabel(shown.unitPrice??draft.unitPrice,context.setup?.assetDecimals,context.setup?.assetSymbol))}${meal.version?' · Published v'+e(meal.version):''}</p><p>Service Time · ${e(serviceHours(shown.windows??draft.windows))} · Beijing time (UTC+8)</p><span class="pill">${meal.listed===true?'Listed':meal.published===false?'Draft · Not published':'Unlisted'}</span>${meal.draft&&meal.published!==false?'<small> · Future draft saved</small>':''}<p>Supported · ${e(meal.financial?.counts?.F??'Not available')} · Available to claim · ${e(meal.financial?.counts?.A??meal.available??'Not available')}</p></div><div class="meal-row-actions">${mealButton('Edit meal','meal-edit',meal.id,busy)}${meal.published===false?mealButton('Publish meal','meal-publish-review',meal.id,busy||capabilities.publish!==true||meal.saved!==true):mealButton(meal.listed===true?'Unlist meal':'List meal','meal-listing',meal.id,busy)}</div></article>`;}).join('');
  const content=view==='overview'?`<div class="overview-grid"><section class="verification-tool"><h2>Check a voucher</h2><p class="muted">Checking does not use the voucher or transfer funds.</p><button class="button" data-live-action="verification-open">Scan or paste voucher</button><p class="muted">Open the scanner or paste a private voucher link.</p></section><section class="metrics-section"><h2>Kitchen at a glance</h2>${overview?`<div class="merchant-metrics">${[['Meals supported',overview.financial?.counts?.F],['Available to claim',overview.financial?.counts?.A],['Claimed, awaiting meal',overview.financial?.counts?.R]].map(([label,value])=>`<section class="stat"><h3>${label}</h3><strong>${e(value??'Not available')}</strong></section>`).join('')}</div>`:'<p class="muted">Kitchen totals are not available yet.</p>'}</section></div><section class="panel">${facts([['Kitchen ID',store.id],['Kitchen contract',store.escrow??context.registration?.escrow],['Owner wallet',context.session?.wallet]])}<a class="button outline" href="#store/${encodeURIComponent(store.id)}">Public kitchen · View only</a></section>`:view==='meals'?`<div class="meals-toolbar">${mealButton('+ Add meal','meal-add','',busy)}</div><p class="muted">Edit a future draft without changing existing meal obligations.</p>${!Object.values(capabilities).some(value=>value===true)?'<p class="notice">Meal forms are available to review and edit. Saving, publishing and listing changes need a supported connection.</p>':''}${menu||'<section class="empty"><h2>No meals yet</h2><p>Add your first meal draft.</p></section>'}`:view==='payouts'?renderPayouts(payouts,payoutsLoading):`<section class="panel"><h2>${view==='verify'?'Voucher verification':'Kitchen payouts'}</h2>${view==='verify'?'<p>Scan a QR code or paste its private link. Checking will not use the voucher.</p><button class="button" data-live-action="verification-open">Scan or paste voucher</button>':'<p>This action is not connected yet.</p><button class="button" disabled>Review payout</button>'}</section>`;
  return `<div class="merchant-shell"><aside class="merchant-sidebar"><h2>${e(store.name)}</h2><p>Owner wallet · ${e(context.session.wallet)}</p><nav aria-label="Kitchen workspace">${views.map(([v,label])=>`<a href="#merchant/${v}" ${view===v?'aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="text-button" href="#stores">Return to kitchens</a></aside><section class="merchant-content"><header class="workspace-heading"><h1>${views.find(([v])=>v===view)[1]}</h1><p>${view==='meals'?'Manage this kitchen’s meals.':'Latest records from your kitchen.'}</p></header>${content}${button('Refresh kitchen','refresh-kitchen',busy,true)}<p class="error" role="alert">${e(error)}</p></section></div>`;
}
export function renderLiveMealEditor(editor,setup={}){
 const d=editor.values,errors=editor.errors??{},reason=editor.reason||'Saving and publishing are not connected for this meal. Your changes remain an unsaved preview.';
 const options=halfHourOptions;
 return `<h2 id="dialog-title">${editor.creating?'Create a meal':'Edit '+e(d.name)}</h2><p class="dialog-subtitle">${editor.creating?'Drafts are not visible in public Kitchens.':'Future changes retain all original meal terms.'}</p><form id="live-meal-form"><fieldset style="border:0;margin:0;padding:0;min-width:0" ${editor.loading||editor.saving?'disabled':''}><div class="form-field"><label for="live-meal-name">Meal name</label><input id="live-meal-name" name="name" maxlength="80" value="${e(d.name)}" aria-describedby="live-error-name"><p class="field-error" id="live-error-name">${e(errors.name??'')}</p></div><div class="form-field"><label for="live-meal-description">Description / content</label><textarea id="live-meal-description" name="description" maxlength="500" aria-describedby="live-error-description">${e(d.description)}</textarea><p class="field-error" id="live-error-description">${e(errors.description??'')}</p></div><section class="form-field image-editor"><h3>Meal image</h3>${mealButton('Upload image','meal-image','',editor.uploading)}<input id="live-meal-image" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Upload meal image" hidden><p class="form-help">Unsaved preview · PNG, JPEG or WebP up to 4 MiB. Images are normalized before use.</p>${d.preview?`<img class="editor-image" src="${e(d.preview)}" alt="Unsaved meal image preview" width="240" height="160">`:''}<p id="live-image-status" role="status">${editor.uploading?'Processing image…':d.photo?'Unsaved image preview':'Current image'}</p><p class="field-error" id="live-error-image">${e(errors.image??'')}</p></section><div class="form-field"><label for="live-meal-price">Future unit price · ${e(setup.assetSymbol??'test USDC')}</label><input id="live-meal-price" name="price" inputmode="decimal" value="${e(d.price)}" aria-describedby="live-error-price"><p class="field-error" id="live-error-price">${e(errors.price??'')}</p></div><section class="form-field"><div class="time-heading"><h3>Service Time</h3><button type="button" class="time-control" data-live-action="meal-add-time" aria-label="Add service time" ${d.windows.length>=2?'disabled':''}><span class="time-icon" aria-hidden="true">+</span></button></div><p class="form-help">Up to two same-day, non-overlapping times · Beijing time (UTC+8). Choose hourly or half-hourly slots; end time may be 24:00. Saved non-half-hour times stay unchanged; reselect a 30-minute slot before saving.</p>${d.windows.map(([start,end],i)=>`<div class="service-time-row"><div><label for="live-meal-start-${i}">Start time</label><select id="live-meal-start-${i}" aria-label="Start time ${i+1}">${options(start)}</select></div><div><label for="live-meal-end-${i}">End time</label><select id="live-meal-end-${i}" aria-label="End time ${i+1}">${options(end,true)}</select></div><button type="button" class="time-control" data-live-action="meal-remove-time" data-time-index="${i}" aria-label="Remove time ${i+1}" ${d.windows.length===1?'disabled':''}><span class="time-icon" aria-hidden="true">−</span></button></div>`).join('')}<p class="field-error">${e(errors.windows??'')}</p></section><p class="notice">${e(reason)}</p><p role="status">${e(editor.status??'')}</p><p class="muted">Draft reference · ${e(editor.mealId??'')}</p><p class="field-error" role="alert">${e(editor.error??'')}</p><div class="order-actions">${mealButton('Save draft','meal-save','',!editor.canSave||editor.uploading||editor.loading||editor.saving)}${mealButton('Review & publish','meal-publish','',!editor.canPublish||editor.uploading||editor.loading||editor.saving)}${editor.imageFailed?mealButton('Retry image upload','meal-retry-image','',editor.saving||!editor.canUpload):''}</div></fieldset>${mealButton('Cancel','meal-close')}</form>`;
}
export function renderLiveStore(store,meals,setup={}){
  if(!store)return '<div class="container page"><h1>Kitchen unavailable</h1><p>Check the connection or return to kitchens.</p><a class="button" href="#stores">Return to kitchens</a></div>';
  return `<div class="container page"><div class="breadcrumb"><a href="#stores">Kitchens</a> / ${e(store.name)}</div><div class="page-heading"><h1>${e(store.name)}</h1><p>Public kitchen · View only · Monad Testnet</p></div>${facts([['Kitchen ID',store.id],['Kitchen contract',store.escrow]])}<div class="public-meal-list">${meals.filter(m=>m.listed===true).map(meal=>`<section class="detail-grid"><div class="live-detail-photo">${photo(meal)}</div><div><h2>${e(meal.name)}</h2><p>${e(meal.description)}</p>${facts([['Price per meal',priceLabel(meal.unitPrice,setup.assetDecimals,setup.assetSymbol)],['Service time',serviceHours(meal.windows)+' · Beijing time (UTC+8)'],['Available to claim',meal.financial?.counts?.A??meal.available]])}<div class="detail-buttons"><button class="button" data-live-action="support-start" data-store-id="${e(store.id)}" data-meal-id="${e(meal.id)}" ${meal.eligible===false?'disabled':''}>Support a meal</button><button class="button outline" data-live-action="claim-start" data-store-id="${e(store.id)}" data-meal-id="${e(meal.id)}" ${meal.eligible===false||!(Number(meal.financial?.counts?.A??meal.available)>0)?'disabled':''}>Claim a meal</button></div><p class="muted">Review this meal before supporting or claiming it. Follow your claim in My meals.</p></div></section>`).join('')||'<p>No listed meals are available.</p>'}</div></div>`;
}

export function renderWalletChooser(choice){
 const busy=choice.loading||choice.signing;
 return `<h2 id="dialog-title">Choose your wallet account</h2>${facts([['Current website account',choice.websiteAccount??'Not signed in']])}<p class="dialog-subtitle">Choose the account this website should use. Your wallet will ask you to sign a login message for that address.</p><label for="wallet-choice">Accounts available to this website</label><select id="wallet-choice" ${busy?'disabled':''}><option value="">Choose an account</option>${choice.accounts.map(address=>`<option value="${e(address)}" ${choice.selected===address?'selected':''}>${e(address)}</option>`).join('')}</select>${!choice.loading&&!choice.accounts.length?'<p class="notice">No accounts are available to this website. Connect an account in your wallet to continue.</p>':''}<p class="form-help">If your account is missing, connect another account using the wallet’s website permissions.</p><p role="status">${choice.loading?'Reading available accounts…':choice.signing?'Check the selected address in your wallet and sign the login message.':''}</p><p class="error" id="wallet-choice-error" role="alert">${e(choice.error??'')}</p><div class="order-actions">${button('Continue with selected account','wallet-confirm',busy||!choice.accounts.includes(choice.selected))}${button('Connect another account','wallet-connect',busy,true)}${button('Cancel','wallet-close',false,true)}</div>`;
}

export const supportState=intent=>intent?.stage??intent?.status??'PENDING';
export function renderSupportFlow(flow,setup={}){
 const intent=flow.intent,id=intent?.intentId??intent?.id,stage=supportState(intent),done=!!intent&&stage==='FINAL_SUCCEEDED',review=flow.review?.review;
 const total=/^\d+$/.test(flow.meal?.unitPrice??'')&&Number.isInteger(flow.quantity)?String(BigInt(flow.meal.unitPrice)*BigInt(flow.quantity)):null;
 const action=(label,name,disabled=false,kind='')=>`<button type="button" class="button ${name==='support-check'?'outline':''}" data-live-action="${name}" data-kind="${kind}" ${disabled?'disabled':''}>${label}</button>`;
 const remaining=flow.quoteClock?Math.max(0,Math.ceil(flow.quoteClock.deadline-flow.quoteClock.serverNow-Math.max(0,Date.now()-flow.quoteClock.receivedAt)/1000)):null;
 const expired=!done&&(flow.quoteExpired===true||remaining===0);
 const walletActions=expired?[]:(flow.preparation?.actions??[]).filter(item=>['approve','fund'].includes(item.kind));
 const quoteTiming=!done&&!expired&&remaining!==null?facts([['Quote deadline',new Date(flow.quoteClock.deadline*1000).toISOString()],['Time remaining',`${Math.floor(remaining/60)}m ${remaining%60}s`]]):'';
 return `<h2 id="dialog-title">${expired?'Quote expired':done?'Thank you for leaving a meal.':intent?'Your contribution':'Support a meal'}</h2>${flow.meal?`<div class="checkout-item"><div class="live-meal-photo">${photo(flow.meal)}</div><div><h3>${e(flow.meal.name)}</h3><p>${e(flow.store?.name)}</p><p>${e(flow.meal.description)}</p></div></div>`:''}${!intent&&!review?`<label for="support-quantity">Meal quantity</label><input id="support-quantity" type="number" min="1" max="10" step="1" value="${e(flow.quantity)}" ${flow.busy?'disabled':''}><div class="checkout-row checkout-total"><span>Estimated total</span><strong>${e(priceLabel(total,setup.assetDecimals,setup.assetSymbol))}</strong></div><p class="muted">One kitchen and one meal. Review the confirmed terms before continuing.</p>${action('Review support','support-review',flow.busy)}`:''}${review&&!intent?`${facts([['Meal',review.name??flow.meal?.name],['Quantity',review.quantity],['Price per meal',priceLabel(review.unitPrice,setup.assetDecimals,setup.assetSymbol)],['Total',priceLabel(review.amount,setup.assetDecimals,setup.assetSymbol)],['Payer wallet',review.payer]])}<p class="notice">Confirm this original contribution, then approve the allowance and send payment separately in your wallet. Creating the request does not confirm payment.</p>${action('Confirm contribution','support-confirm',flow.busy||flow.confirmAttempted)}${flow.confirmAttempted?'<p class="muted">The original confirmation was attempted; its outcome is not yet verified. Check My contributions to recover it; do not create a replacement.</p>':''}`:''}${intent?`${facts([['Contribution reference',id],['Status',expired?'Quote expired':done?'Support confirmed':stage],['Transaction',intent.transactionHash??flow.lastHash??'Not yet confirmed']])}${quoteTiming}${expired?`<p class="notice">This quote has expired; do not approve or pay it. The original contribution remains in My contributions.</p>${flow.canReviewAgain?action('Review support again','support-review-again',flow.busy):'<p class="muted">The original meal is not currently available for another review.</p>'}`:done?`<p class="notice">The original contribution is confirmed. ${flow.catalogRefreshed?'The kitchen’s public meal availability has been refreshed.':'Check progress to refresh the public meal availability.'}</p>`:'<p class="notice">Payment is not confirmed yet. Keep this original contribution reference and check its progress.</p>'}${!done?walletActions.map(item=>`${facts([['Wallet step',item.kind==='approve'?'Allowance approval':'Meal payment'],['Payer',item.account],['Amount',priceLabel(item.amount,setup.assetDecimals,setup.assetSymbol)]])}${action(item.kind==='approve'?'Approve meal allowance':'Send meal payment','support-send',flow.busy||item.allowed!==true||!!flow.attempted?.[item.kind],item.kind)}`).join(''):''}${!done&&!expired&&flow.attempted&&Object.keys(flow.attempted).length?'<p class="muted">A wallet step has already been requested. Pending or uncertain transactions are checked on the original contribution, never sent again automatically.</p>':''}${expired?'':action('Check original progress','support-check',flow.busy)}${!done?[...new Set([...Object.keys(flow.knownHashes??{}),...walletActions.filter(item=>item.canRetryRecord===true).map(item=>item.kind)])].map(kind=>{const hash=flow.knownHashes?.[kind];return `<p class="muted">${e(kind)} transaction${hash?' · '+e(hash):' · Original hash retained'}</p>${action('Retry recording '+kind+' transaction','support-record',flow.busy,kind)}`;}).join(''):''}`:''}<p role="status">${e(flow.status??'')}</p><p class="error" id="support-error" role="alert">${e(flow.error??'')}</p><div class="order-actions"><a class="button outline" href="#contributions">My contributions</a>${action('Close','support-close')}</div><p class="muted">Monad Testnet · Test assets have no real dollar value.</p>`;
}
export function renderContributions({session,orders=[],loading=false,error='',setup={}}){
 return `<div class="container page"><div class="page-heading"><h1>My contributions</h1><p>Continue the original contribution and check its payment.</p></div>${!session?button('Sign in with wallet','login'):facts([['Current wallet',session.wallet]])}${session?button('Refresh contributions','support-orders',loading,true):''}${loading?'<p role="status">Loading your contributions…</p>':session&&!orders.length?'<section class="empty"><h2>No contributions found</h2><p>Your original requests will appear here after confirmation.</p></section>':''}${orders.map(order=>`<article class="order-card"><h2>${e(order.name??order.mealName??'Meal contribution')}</h2>${facts([['Reference',order.intentId??order.id],['Status',supportState(order)==='FINAL_SUCCEEDED'?'Support confirmed':supportState(order)],['Amount',priceLabel(order.amount??order.review?.amount,setup.assetDecimals,setup.assetSymbol)]])}<button class="button outline" data-live-action="support-open" data-intent-id="${e(order.intentId??order.id)}">Check original contribution</button></article>`).join('')}<p class="error" role="alert">${e(error)}</p><a class="text-button" href="#stores">Explore public kitchens</a></div>`;
}

const claimButton=(label,action,disabled=false,attrs='')=>`<button class="button outline" data-live-action="${action}" ${attrs} ${disabled?'disabled':''}>${label}</button>`;
const voucherFacts=voucher=>facts([['Voucher reference',voucher.voucherId??voucher.id],['Kitchen',voucher.store],['Status',voucher.state],['Valid until',voucher.expiresAt?new Date(Number(voucher.expiresAt)*1000).toISOString():'Not available'],['Service time',serviceHours(voucher.terms?.windows)+' · Beijing time (UTC+8)']]);
export function renderClaimFlow(flow){
 const intent=flow.intent,voucher=flow.voucher,review=flow.review?.review,final=!!voucher&&supportState(intent)==='FINAL_SUCCEEDED';
 return `<h2 id="dialog-title">${final?'Your meal voucher is ready':voucher?'Your meal voucher':intent?'Claim progress':'Claim a meal'}</h2>${flow.meal?`<h3>${e(flow.meal.name)}</h3><p>${e(flow.meal.description)}</p>`:''}${!intent&&!voucher&&!review?`<p>Review one available portion from this kitchen. Your claim is complete only when the service confirms it and returns a real voucher.</p>${claimButton('Review claim','claim-review',flow.busy||flow.confirmAttempted)}`:''}${review&&!intent?`${facts([['Meal',review.name],['Description',review.description],['Service time',serviceHours(review.windows)+' · Beijing time (UTC+8)'],['Review reference',flow.review.reviewId]])}<p>Confirm to request this meal. The service processes the claim; no wallet transaction is needed.</p>${claimButton('Confirm claim','claim-confirm',flow.busy||flow.confirmAttempted)}${flow.confirmAttempted?'<p class="notice">Confirmation was attempted; the outcome is not yet verified. Recover the original request in My meals. Do not create a replacement.</p>':''}`:''}${intent&&!voucher?`${facts([['Claim reference',intent.intentId??intent.id],['Status',supportState(intent)]])}<p>A voucher has not been verified yet. Check this original claim.</p>${claimButton('Check original claim','claim-check',flow.busy)}`:''}${voucher?`${voucherFacts(voucher)}<p>${e(voucher.terms?.name??'')}</p><p>${e(voucher.terms?.description??'')}</p>${flow.display?`<div class="qr-wrap"><div id="live-voucher-qr" aria-label="Short-lived voucher QR code"></div><p class="code-string">${e(flow.display.display)}</p><p>Code expires ${e(new Date(flow.display.validUntil*1000).toISOString())}</p>${flow.display.displayUrl?`<a href="${e(flow.display.displayUrl)}">Open private voucher link</a>${claimButton('Copy private link','claim-copy-link',flow.busy)}<p role="status">${e(flow.display.copyStatus??'')}</p>${flow.display.copyFallback?`<label for="voucher-private-link">Private voucher link</label><input id="voucher-private-link" type="text" readonly autocomplete="off" spellcheck="false" value="${e(flow.display.displayUrl)}">`:''}`:''}</div><p>Show this code only at the kitchen. Showing a code does not confirm handover.</p>`:claimButton('Show QRcode','claim-display',flow.busy||voucher.state!=='R'||voucher.locked||voucher.marked||voucher.pending)}<p>Keep this account signed in while the kitchen checks your fresh code. The kitchen owner uses a separate browser or browser profile.</p>`:''}<p class="error" role="alert">${e(flow.error??'')}</p><div class="order-actions"><a class="button outline" href="#mine">My meals</a>${claimButton('Close','claim-close')}</div>`;
}
export function renderMyMeals({session,vouchers=[],intents=[],loading=false,error=''}){
 if(!session){vouchers=[];intents=[];}
 return `<div class="container page"><div class="page-heading"><h1>My meals</h1><p>Your original claims and meal vouchers from the connected service.</p></div>${session?claimButton('Refresh my meals','claim-records',loading):button('Sign in with wallet','login')}${loading?'<p role="status">Loading meal records…</p>':''}${session&&!loading&&!vouchers.length&&!intents.length?'<p>No meal records found.</p>':''}${vouchers.map(v=>`<article class="order-card"><h2>${e(v.terms?.name??'Meal voucher')}</h2>${voucherFacts(v)}${claimButton('Open voucher','claim-voucher',false,`data-voucher-id="${e(v.voucherId??v.id)}"`)}</article>`).join('')}${intents.map(i=>`<article class="order-card"><h2>Original meal claim</h2>${facts([['Reference',i.intentId??i.id],['Status',supportState(i)]])}${claimButton('Check original claim','claim-open',false,`data-intent-id="${e(i.intentId??i.id)}"`)}</article>`).join('')}<p class="error" role="alert">${e(error)}</p><a href="#stores">Explore kitchens</a></div>`;
}

export function renderVerificationEntry(flow){
 const failedLock=flow.intent?.action==='lock'&&flow.intent?.stage==='FINAL_REVERT';
 const checked=flow.checked,record=failedLock?null:flow.case,used=record?.state==='H'||record?.state==='S',locked=!!flow.lockAttempted||!!flow.intent||!!record;
 const action=(label,name,disabled=false,attrs='')=>`<button class="button outline" data-live-action="${name}" ${attrs} ${disabled?'disabled':''}>${label}</button>`;
 const details=value=>facts([['Kitchen',value.store],['Meal',value.terms?.name],['Description',value.terms?.description],['Portions','1'],['Voucher',value.voucherId??value.voucher??value.id],['Service time',serviceHours(value.terms?.windows)+' · Beijing time (UTC+8)'],['Valid until',value.expiresAt?new Date(Number(value.expiresAt)*1000).toISOString():'Unavailable']]);
 return `<h2 id="dialog-title">${failedLock?'Voucher reservation failed':used?'Voucher used':record?'Meal handover':'Check a voucher'}</h2>${!locked?`<p>Scan the short-lived QR code or paste its private link. Reading a code does not use a voucher. Ask the recipient to stay signed in and show a fresh code. Sign in as the owner in a separate browser or browser profile; tabs in the same browser share the session.</p><label for="verification-input">Private link or verification code</label><textarea id="verification-input" rows="2" autocomplete="off" spellcheck="false" ${flow.busy?'disabled':''}></textarea><div class="order-actions">${action('Read pasted code','verification-parse',flow.busy)}${action('Open camera','verification-camera',flow.cameraPending||flow.busy)}${action('Stop camera','verification-stop',flow.busy)}</div><video id="verification-camera" autoplay playsinline muted aria-label="Voucher scanner" ${flow.scanning?'':'hidden'}></video><p role="status">${flow.code?'Code read. Voucher validity has not been checked.':e(flow.status??'')}</p>${action('Check voucher','verification-check',flow.busy||!flow.code)}`:''}${checked&&!record&&!failedLock?`${details(checked)}<p class="notice">Valid for this kitchen when checked. Checking alone does not reserve or use the voucher.</p>${action('Reserve voucher for handover','verification-reserve',flow.busy||flow.lockAttempted)}`:''}${flow.lockAttempted&&!flow.intent&&!record?'<p>Reservation was attempted; its outcome is not verified. Refresh kitchen requests to recover it. Do not reserve again.</p>':''}${locked&&flow.status?`<p role="status">${e(flow.status)}</p>`:''}${flow.intent?facts([['Original request',flow.intent.intentId??flow.intent.id],['Action',flow.intent.action],['Request status',supportState(flow.intent)],['Transaction',flow.intent.transactionHash??flow.intent.result?.transactionHash]]):''}${record?`${details(record)}${facts([['Voucher state',used?'Used':record.state],['Handover case',record.id]])}${used?`<p>${record.state==='S'?'Settlement is confirmed in the voucher record.':'Meal handover is confirmed. After the waiting period, the owner reviews and sends settlement from Payouts.'}</p><a class="button outline" href="#merchant/payouts">Payouts</a>`:`<p>A reservation does not mean the meal has been handed over.</p><label class="checkbox"><input type="checkbox" id="verification-handover-confirm" ${flow.busy||flow.handoverAttempted?'disabled':''}> I have physically handed over this meal.</label>${action('Confirm handover','verification-handover',flow.busy||flow.handoverAttempted||record.state!=='R'||record.marked||record.pending)}`}`:''}${flow.intent||record?action('Check original progress','verification-progress',flow.busy):''}<section><h3>Kitchen requests</h3>${action('Refresh kitchen requests','verification-records',flow.busy)}${(flow.records??[]).map(item=>`<div class="order-card">${facts([['Original request',item.intentId??item.id],['Action',item.action],['Status',supportState(item)]])}${action('Open original request','verification-restore',flow.busy,`data-intent-id="${e(item.intentId??item.id)}"`)}</div>`).join('')}</section><p class="error" role="alert">${e(flow.error??'')}</p>${action('Close','verification-close')}`;
}

const settlementWait=(payout,serverTime,receivedAt)=>Number.isFinite(payout?.settleEligibleAt)&&Number.isFinite(serverTime)?Math.max(0,Math.ceil(payout.settleEligibleAt-serverTime-Math.max(0,Date.now()-receivedAt)/1000)):null;
const settlementFacts=payout=>facts([['Voucher',payout.id??payout.voucherId],['Amount',priceLabel(payout.amount,payout.assetDecimals,payout.assetSymbol)],['Receiver',payout.receiver],['Asset',payout.asset],['Chain',payout.chainId]]);
const settlementButton=(label,action,disabled=false,attrs='')=>`<button class="button outline" data-live-action="${action}" ${attrs} ${disabled?'disabled':''}>${label}</button>`;
const settlementCountdown=(p,serverTime,receivedAt)=>{const remaining=settlementWait(p,serverTime,receivedAt);return remaining===null?'Waiting for confirmed report evidence':`<span data-settlement-countdown data-eligible-at="${p.settleEligibleAt}" data-server-time="${serverTime}" data-received-at="${receivedAt}">${remaining>0?`Waiting period: ${remaining}s remaining.`:'Waiting period ended. Check original progress to verify eligibility.'}</span>`;};
const settlementTxLink=(chainId,hash)=>Number(chainId)===10143&&/^0x[0-9a-fA-F]{64}$/.test(hash??'')?`<a href="https://testnet.monadscan.com/tx/${hash}" target="_blank" rel="noopener noreferrer">View transaction on Monadscan</a>`:'';
export function renderPayouts(data,loading=false){
 return `<section class="panel"><h2>Kitchen payouts</h2><p>After confirmed handover, wait for the service’s 180-second eligibility period. Review and confirm settlement, then explicitly send the wallet transaction. Funds do not arrive automatically.</p>${settlementButton('Refresh payouts','settlement-list',loading)}${loading?'<p>Loading payouts…</p>':''}${(data?.items??[]).map(p=>{const wait=settlementWait(p,data.serverTime,data.receivedAt),final=p.state==='S'&&p.settlementIntents?.some(i=>i.stage==='FINAL_SUCCEEDED');return `<article class="order-card">${settlementFacts(p)}${(p.settlementIntents??[]).map(i=>settlementTxLink(p.chainId,i.transactionHash??i.result?.transactionHash)).join('')}<p>${final?'Settled':p.state==='S'?'Settlement record found; verify original transaction':settlementCountdown(p,data.serverTime,data.receivedAt)}</p>${settlementButton('Open payout','settlement-open',loading,`data-voucher-id="${e(p.id)}"`)}${(p.settlementIntents??[]).map(i=>settlementButton('Open original settlement','settlement-open',loading,`data-voucher-id="${e(p.id)}" data-intent-id="${e(i.intentId??i.id)}"`)).join('')}</article>`;}).join('')}${data&&!data.items?.length?'<p>No payout records found.</p>':''}</section>`;
}
export function renderSettlementFlow(flow){
 const id=flow.intent?.intentId??flow.intent?.id,p=flow.payout,review=flow.review?.review,wait=settlementWait(p,flow.serverTime,flow.receivedAt),step=flow.preparation?.actions?.find(item=>item.kind==='settle');
 const hash=flow.intent?.transactionHash??flow.intent?.result?.transactionHash??flow.transactionHash;
 return `<h2 id="dialog-title">${flow.settled?'Settled':'Settlement review'}</h2>${settlementFacts(review??p)}${settlementTxLink(p.chainId,hash)}${flow.settled?`<p>Settlement is confirmed by the original transaction and voucher record.</p>${facts([['Transaction',hash]])}`:`<p>${settlementCountdown(p,flow.serverTime,flow.receivedAt)}</p>${!flow.review&&!id?settlementButton('Review settlement','settlement-review',flow.busy||wait!==0||flow.confirmAttempted||p.state!=='H'||!!p.settlementIntents?.length):''}${review&&!id?`${facts([['Review reference',flow.review.reviewId]])}${settlementButton('Confirm settlement','settlement-confirm',flow.busy||flow.confirmAttempted)}${flow.confirmAttempted?'<p>Confirmation outcome is not yet verified. Refresh Payouts to recover the original request; do not create a replacement.</p>':''}`:''}${id?`${facts([['Original request',id],['Status',flow.intent.stage],['Transaction',hash]])}${settlementButton('Send settlement wallet tx','settlement-send',flow.busy||step?.allowed!==true||flow.sendAttempted||flow.intent.stage==='FINAL_SUCCEEDED'||p.state!=='H')}${step?.canRetryRecord?settlementButton('Retry recording original transaction','settlement-record',flow.busy):''}`:''}${settlementButton('Check original progress','settlement-check',flow.busy)}`}<p role="status">${e(flow.status??'')}</p><p class="error" role="alert">${e(flow.error??'')}</p><a class="button outline" href="#merchant/payouts">Payouts</a>${settlementButton('Close','settlement-close')}`;
}

// Publication view receives a normalized review and independently confirmed phases.
export function renderMealPublishFlow(flow,setup={}){
 const review=flow.review,publish=flow.publish,listing=flow.listing,publicMeal=flow.publicMeal;
 const matches=!!review&&!!publicMeal&&publicMeal.id?.replace(/^0x/,'')===review.mealId?.replace(/^0x/,'')&&String(publicMeal.version)===String(review.version);
 const published=publish?.stage==='FINAL_SUCCEEDED',needsListing=review?.needsListing??(review?.targetListed===true);
 const ready=published&&matches&&(review.targetListed===true?(!needsListing||listing?.stage==='FINAL_SUCCEEDED')&&publicMeal.listed===true:review.targetListed===false&&publicMeal.listed===false);
 const title=ready?(publicMeal.listed?'Meal published and listed':'Meal published · Unlisted'):publish?'Meal publication progress':'Review meal publication';
 const action=(label,name,disabled=false)=>`<button class="button outline" data-live-action="${name}" ${disabled?'disabled':''}>${label}</button>`;
 return `<h2 id="dialog-title">${title}</h2>${review?`${facts([['Private draft ID',review.draftId],['Saved draft revision',review.revision],['Meal ID',review.mealId],['Target version',review.version],['Meal',review.name],['Description',review.description],['Price per meal',priceLabel(review.unitPrice,setup.assetDecimals,setup.assetSymbol)],['Service time',serviceHours(review.windows)+' · Beijing time (UTC+8)'],['Listing after publication',review.targetListed===true?'Listed':review.targetListed===false?'Unlisted':'Not verified']])}<p>Publish these saved details only. Existing orders and vouchers keep their original meal version and terms.</p>`:'<p>Load the saved draft review before confirming publication.</p>'}${!review&&!publish?action('Review saved meal','meal-publish-review-current',flow.busy||flow.connected!==true||flow.confirmAttempted):''}${!publish?action('Confirm meal publication','meal-publish-confirm',flow.connected!==true||flow.busy||!review||flow.confirmAttempted):''}${flow.confirmAttempted&&!publish?'<p>Publication confirmation was attempted; its outcome is not verified. Recover the original request instead of creating a replacement.</p>':''}${publish?`${facts([['Original publication request',publish.id],['Publication status',publish.stage],['Publication transaction',publish.transactionHash]])}${needsListing?facts([['Listing status',listing?.stage??'Waiting for publication'],['Listing transaction',listing?.transactionHash]]):'<p>The existing listing state is retained.</p>'}${!ready?'<p>The public meal is not yet verified at the target version and listing state. Saving a draft or receiving a transaction hash does not make it available for support or claims.</p>':''}${action('Check original publication','meal-publish-check',flow.connected!==true||flow.busy)}`:''}${(flow.records??[]).filter(item=>item.action==='publish').map(item=>`<p>Original publication · ${e(item.version)} · ${e(item.stage)}</p><button class="button outline" data-live-action="meal-publish-restore" data-intent-id="${e(item.intentId??item.id)}" ${flow.busy?'disabled':''}>Open original publication</button>`).join('')}${flow.connected!==true?'<p>Publication actions are awaiting connection.</p>':''}<p class="error" role="alert">${e(flow.error??'')}</p>${action('Close','meal-publish-close')}`;
}
